{"content":"# ars.R -- Adaptive Rejection Sampling (ARS) after Gilks & Wild (1992).
#
#   Gilks, W. R., & Wild, P. (1992). Adaptive rejection sampling for Gibbs
#   sampling. Journal of the Royal Statistical Society: Series C (Applied
#   Statistics), 41(2), 337-348.
#
# Exposes two main entry points:
#   * ars()  -- draw iid samples from a univariate log-concave density.
#   * test() -- formal stochastic test suite with known truths.
#
# Design notes (modular, consistent snake_case, base R only):
#   * Every discrete task is a small helper: input validation, density
#     coercion / evaluation, log-density derivatives, abscissae
#     initialization, upper/lower hull construction, envelope sampling,
#     log-concavity checking, and the main ARS loop.
#   * The primary input is a *vectorized* (possibly unnormalized) density
#     function, e.g. `dnorm`, `dexp`, or `function(x) dnorm(x) * 2`.
#     R expressions / formulas / strings of `x` are also accepted and are
#     coerced to vectorized closures of `x`.
#   * Log-concavity is checked at initialization and every time a new
#     abscissa enters the hull; violations raise an informative error.
#
# Quick example:
#   source("/app/ars.R")
#   x <- ars(1000, dnorm)                    # standard normal
#   y <- ars(1000, function(x) dexp(x), a = 0)  # Exp(1) on [0, Inf)
#   test()                                   # run the formal test suite

# ---------------------------------------------------------------------------
# 1. Input validation
# ---------------------------------------------------------------------------

validate_sample_count <- function(n) {
  if (length(n) != 1L || !is.numeric(n) || is.na(n) || is.nan(n) ||
      !is.finite(n) || floor(n) != n || n < 1L) {
    stop("ars: 'n' must be a single positive integer (number of points to sample); ",
         sprintf("got %s.", paste(deparse(n), collapse = "")), call. = FALSE)
  }
  as.integer(n)
}

validate_domain <- function(a, b) {
  if (length(a) != 1L || length(b) != 1L || !is.numeric(a) || !is.numeric(b) ||
      is.na(a) || is.na(b) || is.nan(a) || is.nan(b)) {
    stop("ars: domain bounds 'a' and 'b' must be single numeric values (-Inf/Inf allowed).",
         call. = FALSE)
  }
  if (!(a < b)) {
    stop(sprintf("ars: invalid domain: need a < b, got a = %s, b = %s.",
                 format(a), format(b)), call. = FALSE)
  }
  list(a = as.numeric(a), b = as.numeric(b))
}

validate_initial_points <- function(x0, a, b) {
  if (is.null(x0)) return(NULL)
  if (!is.numeric(x0) || any(is.na(x0)) || any(!is.finite(x0))) {
    stop("ars: 'x0' initial abscissae must be finite numeric values strictly inside (a, b).",
         call. = FALSE)
  }
  x0 <- sort(unique(as.numeric(x0)))
  if (length(x0) < 2L) {
    stop("ars: need at least two distinct initial abscissae in 'x0'.", call. = FALSE)
  }
  if (any(x0 <= a) || any(x0 >= b)) {
    stop("ars: every 'x0' abscissa must lie strictly inside (a, b).", call. = FALSE)
  }
  x0
}

# ---------------------------------------------------------------------------
# 2. Density coercion / evaluation (vectorized)
# ---------------------------------------------------------------------------

# Coerce a function / expression / formula / string of `x` into a closure.
as_density_function <- function(g) {
  if (is.function(g)) return(g)
  if (inherits(g, "formula")) {
    expr <- attr(stats::terms(g), "variables")[[2L]]
    if (is.null(expr)) stop("ars: could not parse density formula; use e.g. ~ dnorm(x).",
                            call. = FALSE)
    return(function(x) eval(expr, envir = list(x = x)))
  }
  if (is.character(g) && length(g) == 1L) {
    expr <- parse(text = g)[[1L]]
    return(function(x) eval(expr, envir = list(x = x)))
  }
  if (is.expression(g) && length(g) >= 1L) {
    expr <- g[[1L]]
    return(function(x) eval(expr, envir = list(x = x)))
  }
  if (is.language(g)) {
    return(function(x) eval(g, envir = list(x = x)))
  }
  stop("ars: density 'g' must be a vectorized function of x (e.g. dnorm), ",
       "or an R expression / formula / string in x.", call. = FALSE)
}

# Build the vectorized density evaluator, forwarding extra args (e.g. mean/sd).
make_density_evaluator <- function(dens_fn, dens_args) {
  force(dens_fn); force(dens_args)
  function(x) {
    x <- as.numeric(x)
    v <- tryCatch(do.call(dens_fn, c(list(x), dens_args)),
                  error = function(e) {
                    stop(sprintf("ars: density evaluation failed: %s", conditionMessage(e)),
                         call. = FALSE)
                  })
    if (!is.numeric(v) || length(v) != length(x)) {
      stop("ars: density must be vectorized: f(c(x1, x2)) must return a numeric ",
           "vector of length 2.", call. = FALSE)
    }
    if (any(is.na(v)) || any(is.nan(v))) {
      stop("ars: density returned NA/NaN; density must be defined (possibly 0) at every x.",
           call. = FALSE)
    }
    if (any(v < 0)) {
      stop("ars: density returned negative value(s); densities must be >= 0.", call. = FALSE)
    }
    v
  }
}

# h(x) = log g(x); h = -Inf wherever g(x) == 0. Positive-Inf is an error.
make_log_density <- function(eval_dens) {
  force(eval_dens)
  function(x) {
    v <- eval_dens(x)
    h <- log(v)
    h[v == 0] <- -Inf
    if (any(is.infinite(h) & h > 0)) {
      stop("ars: log-density is +Inf somewhere; density must be finite.", call. = FALSE)
    }
    h
  }
}

# Explicitly verify the vectorized contract on two distinct interior points.
check_vectorized <- function(eval_dens, p1, p2) {
  probe <- suppressWarnings(c(p1, p2))
  v <- tryCatch(eval_dens(probe),
                error = function(e) {
                  stop(sprintf(paste0("ars: density is not vectorized Usable: ",
                                      "f(c(x1, x2)) failed with: %s"),
                               conditionMessage(e)), call. = FALSE)
                })
  if (length(v) != 2L || !is.numeric(v)) {
    stop("ars: density must be vectorized: f(c(x1, x2)) must return length-2 numeric.",
         call. = FALSE)
  }
  invisible(TRUE)
}

# ---------------------------------------------------------------------------
# 3. Log-density derivatives (analytic if supplied, numeric otherwise)
# ---------------------------------------------------------------------------

numeric_deriv_step <- function(x) sqrt(.Machine$double.eps) * (1 + abs(x))

# Central differences with one-sided fallback at support boundaries.
numeric_log_deriv <- function(eval_h, x) {
  x <- as.numeric(x)
  out <- numeric(length(x))
  for (i in seq_along(x)) {
    xi <- x[i]
    s <- numeric_deriv_step(xi)
    hp <- eval_h(xi + s)
    hm <- eval_h(xi - s)
    h0 <- eval_h(xi)
    if (is.finite(hp) && is.finite(hm)) {
      out[i] <- (hp - hm) / (2 * s)
    } else if (is.finite(hp) && is.finite(h0)) {
      out[i] <- (hp - h0) / s
    } else if (is.finite(hm) && is.finite(h0)) {
      out[i] <- (h0 - hm) / s
    } else {
      stop("ars: cannot compute log-density derivative at x = ",
           format(xi), "; density is 0 / undefined on both sides.", call. = FALSE)
    }
  }
  out
}

make_log_derivative <- function(dlogdens, eval_h) {
  force(eval_h)
  if (is.null(dlogdens)) {
    return(function(x) numeric_log_deriv(eval_h, x))
  }
  if (!is.function(dlogdens)) {
    stop("ars: derivative of the log-density must be a function of x (or NULL).",
         call. = FALSE)
  }
  function(x) {
    x <- as.numeric(x)
    d <- tryCatch(dlogdens(x),
                  error = function(e) {
                    stop(sprintf("ars: log-density derivative failed: %s",
                                 conditionMessage(e)), call. = FALSE)
                  })
    if (!is.numeric(d) || length(d) != length(x) || any(is.na(d) | is.nan(d))) {
      stop("ars: log-density derivative must return a numeric vector of length(x) with no NA.",
           call. = FALSE)
    }
    as.numeric(d)
  }
}

# ---------------------------------------------------------------------------
# 4. Log-concavity checks (Gilks & Wild Eqs. 4-6守住 concave envelope)
# ---------------------------------------------------------------------------

concavity_tolerance <- function(ha, hb) 1e-7 * (1 + abs(ha) + abs(hb))

# Full pairwise check: every tangent must dominate every abscissa, and slopes
# must be non-increasing in x. Called at startup and after each hull update.
check_log_concavity <- function(x, h, hp) {
  k <- length(x)
  if (k < 2L) stop("ars: internal error: fewer than two abscissae.", call. = FALSE)
  slope_tol <- 1e-6 * (1 + max(abs(hp[is.finite(hp)]), 0))
  if (any(!is.finite(h)) || any(!is.finite(hp))) {
    stop("ars: log-density or its derivative is not finite at the abscissae; ",
         "check the starting points / domain.", call. = FALSE)
  }
  if (any(diff(hp) > slope_tol)) {
    stop("ars: density does not appear to be log-concave ",
         "(log-density slopes are not non-increasing).", call. = FALSE)
  }
  for (j in seq_len(k)) {
    pred <- h[j] + hp[j] * (x - x[j])
    tol <- concavity_tolerance(h[j], h)
    if (any(h > pred + tol)) {
      stop("ars: density does not appear to be log-concave ",
           "(a tangent lies strictly below the log-density).", call. = FALSE)
    }
  }
  invisible(TRUE)
}

# ---------------------------------------------------------------------------
# 5. Hull construction (upper tangents, lower chords, envelope pieces)
# ---------------------------------------------------------------------------

# Upper hull intersection points z_0 = a < z_1 < ... < z_{k-1} < z_k = b.
compute_knots <- function(x, h, hp, a, b) {
  k <- length(x)
  z <- numeric(k + 1L)
  z[1L] <- a
  z[k + 1L] <- b
  for (j in seq_len(k - 1L)) {
    denom <- hp[j] - hp[j + 1L]
    if (abs(denom) < 1e-12) {
      # Parallel tangents: only valid for (locally) linear log-density,
      # where the two tangents coincide.
      ij <- h[j] - hp[j] * x[j]
      ij1 <- h[j + 1L] - hp[j + 1L] * x[j + 1L]
      if (abs(ij - ij1) > 1e-8 * (1 + abs(ij) + abs(ij1))) {
        stop("ars: density does not appear to be log-concave ",
             "(parallel tangents do not coincide).", call. = FALSE)
      }
      z[j + 1L] <- (x[j] + x[j + 1L]) / 2
    } else {
      z[j + 1L] <- (h[j + 1L] - h[j] - x[j + 1L] * hp[j + 1L] + x[j] * hp[j]) / denom
    }
  }
  if (any(!is.finite(z[2L:k])) || any(diff(z) <= 1e-10)) {
    stop("ars: density does not appear to be log-concave ",
         "(upper-hull knots are not strictly increasing).", call. = FALSE)
  }
  z
}

# Unnormalized weight of exp(a_j + m_j * x) over [L, U].
piece_weight <- function(intercept, slope, L, U) {
  if (abs(slope) < 1e-12) {
    if (!(is.finite(L) && is.finite(U))) {
      stop("ars: envelope is improper (flat upper hull on an unbounded piece); ",
           "move the starting abscissae closer to the mode.", call. = FALSE)
    }
    return((U - L) * exp(intercept))
  }
  if (is.infinite(L) && is.infinite(U)) {
    stop("ars: envelope is improper (one piece covers the whole line).", call. = FALSE)
  }
  if (is.infinite(U)) { # L finite, need slope < 0
    if (!(slope < 0)) {
      stop("ars: envelope is improper on the right tail; ",
           "starting abscissae do not bracket the mode.", call. = FALSE)
    }
    return(exp(intercept + slope * L) / abs(slope))
  }
  if (is.infinite(L)) { # U finite, need slope > 0
    if (!(slope > 0)) {
      stop("ars: envelope is improper on the left tail; ",
           "starting abscissae do not bracket the mode.", call. = FALSE)
    }
    return(exp(intercept + slope * U) / slope)
  }
  eu <- exp(intercept + slope * U)
  el <- exp(intercept + slope * L)
  w <- (eu - el) / slope
  if (!is.finite(w) || w <= 0) {
    stop("ars: envelope piece has non-finite/non-positive weight; ",
         "check the density scale and starting points.", call. = FALSE)
  }
  w
}

# Full envelope: knots, per-piece lines u(x) = intercept + slope * x, weights.
compute_hull <- function(x, h, hp, a, b) {
  k <- length(x)
  z <- compute_knots(x, h, hp, a, b)
  L <- z[1L:k]; U <- z[2L:(k + 1L)]
  slope <- hp
  intercept <- h - hp * x
  w <- numeric(k)
  for (j in seq_len(k)) w[j] <- piece_weight(intercept[j], slope[j], L[j], U[j])
  if (any(!is.finite(w)) || any(w <= 0) || sum(w) <= 0) {
    stop("ars: envelope weights are invalid; check density and starting points.",
         call. = FALSE)
  }
  list(x = x, h = h, hp = hp, z = z, L = L, U = U,
       slope = slope, intercept = intercept, w = w, cumw = cumsum(w) / sum(w))
}

upper_hull <- function(hull, xstar) {
  j <- findInterval(xstar, hull$z, rightmost.closed = TRUE)
  j <- pmin(pmax(j, 1L), length(hull$slope))
  hull$intercept[j] + hull$slope[j] * xstar
}

# Chord lower bound on [x_1, x_k]; -Inf outside (squeezing then always fails).
lower_hull <- function(x, h, xstar) {
  k <- length(x)
  if (xstar < x[1L] || xstar > x[k]) return(-Inf)
  i <- findInterval(xstar, x, rightmost.closed = TRUE)
  i <- pmin(pmax(i, 1L), k - 1L)
  ((x[i + 1L] - xstar) * h[i] + (xstar - x[i]) * h[i + 1L]) / (x[i + 1L] - x[i])
}

# Draw one proposal from the piecewise-exponential envelope s(x) ~ exp(u(x)).
sample_from_envelope <- function(hull) {
  u <- stats::runif(1L)
  j <- findInterval(u, hull$cumw) + 1L
  j <- pmin(pmax(j, 1L), length(hull$w))
  L <- hull$L[j]; U <- hull$U[j]; m <- hull$slope[j]
  if (abs(m) < 1e-12) {
    return(list(xstar = stats::runif(1L, L, U), uval = upper_hull(hull, stats::runif(1L, 0, 0) + (L + U) / 2 * 0 + (L + U) / 2 * 0 + stats::runif(1L, L, U) * 0 + (L + U) / 2, j = j)))
  }
  if (is.infinite(U)) {
    xs <- L + stats::rexp(1L) / abs(m)
  } else if (is.infinite(L)) {
    xs <- U - stats::rexp(1L) / m
  } else {
    span <- U - L
    e <- exp(m * span)
    v <- stats::runif(1L)
    if (m < 0 && e == 0) {
      xs <- L + log(1 - v) / m
    } else {
      xs <- L + log(1 + v * (e - 1)) / m
    }
    xs <- pmin(pmax(xs, L), U)
  }
  list(xstar = as.numeric(xs), uval = hull$intercept[j] + m * as.numeric(xs), j = j)
}

# ---------------------------------------------------------------------------
# 6. Starting abscissae (adaptive bracketing of the mode)
# ---------------------------------------------------------------------------

candidate_grid <- function(a, b) {
  if (is.finite(a) && is.finite(b)) {
    return(a + (b - a) * c(0.2, 0.4, 0.6, 0.8))
