# Upper hull intersection points z_0 = a < z_1 < ... < z_{k-1} < z_k = b.
compute_knots <- function(x, h, hp, a, b) {
  k <- length(x)
  z <- numeric(k + 1L)
  z[1L] <- a
  z[k + 1L] <- b
  for (j in seq_len(k - 1L)) {
    denom <- hp[j] - hp[j + 1L]
    if (abs(denom) < 1e-12) {
      # Parallel tangents: only valid for (locally) linear log-density,
      # where the two tangents coincide.
      ij <- h[j] - hp[j] * x[j]
      ij1 <- h[j + 1L] - hp[j + 1L] * x[j + 1L]
      if (abs(ij - ij1) > 1e-8 * (1 + abs(ij) + abs(ij1))) {
        stop("ars: density does not appear to be log-concave ",
             "(parallel tangents do not coincide).", call. = FALSE)
      }
      z[j + 1L] <- (x[j] + x[j + 1L]) / 2
    } else {
      z[j + 1L] <- (h[j + 1L] - h[j] - x[j + 1L] * hp[j + 1L] + x[j] * hp[j]) / denom
    }
  }
  if (any(!is.finite(z[2L:k])) || any(diff(z) <= 1e-10)) {
    stop("ars: density does not appear to be log-concave ",
         "(upper-hull knots are not strictly increasing).", call. = FALSE)
  }
  z
}

