# Unnormalized weight of exp(a_j + m_j * x) over [L, U].
piece_weight <- function(intercept, slope, L, U) {
  if (abs(slope) < 1e-12) {
    if (!(is.finite(L) && is.finite(U))) {
      stop("ars: envelope is improper (flat upper hull on an unbounded piece); ",
           "move the starting abscissae closer to the mode.", call. = FALSE)
    }
    return((U - L) * exp(intercept))
  }
  if (is.infinite(L) && is.infinite(U)) {
    stop("ars: envelope is improper (one piece covers the whole line).", call. = FALSE)
  }
  if (is.infinite(U)) { # L finite, need slope < 0
    if (!(slope < 0)) {
      stop("ars: envelope is improper on the right tail; ",
           "starting abscissae do not bracket the mode.", call. = FALSE)
    }
    return(exp(intercept + slope * L) / abs(slope))
  }
  if (is.infinite(L)) { # U finite, need slope > 0
    if (!(slope > 0)) {
      stop("ars: envelope is improper on the left tail; ",
           "starting abscissae do not bracket the mode.", call. = FALSE)
    }
    return(exp(intercept + slope * U) / slope)
  }
  eu <- exp(intercept + slope * U)
  el <- exp(intercept + slope * L)
  w <- (eu - el) / slope
  if (!is.finite(w) || w <= 0) {
    stop("ars: envelope piece has non-finite/non-positive weight; ",
         "check the density scale and starting points.", call. = FALSE)
  }
  w
}

# Full envelope: knots, per-piece lines u(x) = intercept + slope * x, weights.
compute_hull <- function(x, h, hp, a, b) {
  k <- length(x)
  z <- compute_knots(x, h, hp, a, b)
  L <- z[1L:k]; U <- z[2L:(k + 1L)]
  slope <- hp
  intercept <- h - hp * x
  w <- numeric(k)
  for (j in seq_len(k)) w[j] <- piece_weight(intercept[j], slope[j], L[j], U[j])
  if (any(!is.finite(w)) || any(w <= 0) || sum(w) <= 0) {
    stop("ars: envelope weights are invalid; check density and starting points.",
         call. = FALSE)
  }
  list(x = x, h = h, hp = hp, z = z, L = L, U = U,
       slope = slope, intercept = intercept, w = w, cumw = cumsum(w) / sum(w))
}

upper_hull <- function(hull, xstar) {
  j <- findInterval(xstar, hull$z, rightmost.closed = TRUE)
  j <- pmin(pmax(j, 1L), length(hull$slope))
  hull$intercept[j] + hull$slope[j] * xstar
}

# Chord lower bound on [x_1, x_k]; -Inf outside (squeezing then always fails).
lower_hull <- function(x, h, xstar) {
  k <- length(x)
  if (xstar < x[1L] || xstar > x[k]) return(-Inf)
  i <- findInterval(xstar, x, rightmost.closed = TRUE)
  i <- pmin(pmax(i, 1L), k - 1L)
  ((x[i + 1L] - xstar) * h[i] + (xstar - x[i]) * h[i + 1L]) / (x[i + 1L] - x[i])
}
